import inspect
from click.testing import CliRunner
base = {'removed': None, 'replaced': None, 'deleted': 'old', 'empty': ''}
overrides = {'replaced': 'new', 'deleted': None, 'added': None}
runner = CliRunner(env=base)
merged = dict(base, **overrides)
assert runner.make_env(overrides) == merged
assert runner.make_env(overrides, strip_none=False) == merged
assert runner.make_env(overrides, strip_none=True) == {'replaced': 'new', 'empty': ''}
assert runner.make_env(strip_none=True) == {'deleted': 'old', 'empty': ''}
assert runner.make_env({}, strip_none=True) == {'deleted': 'old', 'empty': ''}
assert runner.make_env() == base
assert base == {'removed': None, 'replaced': None, 'deleted': 'old', 'empty': ''}
assert overrides == {'replaced': 'new', 'deleted': None, 'added': None}
assert CliRunner().make_env(strip_none=True) == {}
assert inspect.signature(CliRunner.make_env).parameters['strip_none'].kind is inspect.Parameter.KEYWORD_ONLY
'@ | python -; if ($LASTEXITCODE -eq 0) { python -m pytest -q -p no:cacheprovider tests\test_testing.py }; git diff --check; git status --short --untracked-files=all

